#!/usr/bin/env python3
"""Compare the files regenerated by a rerun of the UM-2 computations with the committed versions.

Run it inside a clone of the repository after rerunning the computations and the document build:
    python3 universe_model_2/tools/compare_outputs.py
It lists every file that git reports as modified and, for each JSON file under outputs/ or reports/, compares the old
(committed, HEAD) and the new (regenerated) content: numbers to a relative tolerance (default 1e-9; values below 1e-10 in
magnitude, i.e. round-off-level quantities, are compared absolutely), strings exactly.  Run times (keys ending in
'runtime_s') and the free-text 'detail' of report checks may differ and are listed separately.  Any other modified file
(.tex, .pdf, .png, .md, ...) is reported as CHANGED: with the software versions listed in PROVENANCE these are rebuilt
byte-identical, with other versions of pandoc or TeX they may differ in bytes only.
Exit code 0 iff no number differs beyond the tolerance, no key or array length differs, and no other file changed.
"""
import json
import subprocess
import sys

TOL = float(sys.argv[1]) if len(sys.argv) > 1 else 1e-9


def git(*args):
    return subprocess.run(['git'] + list(args), capture_output=True, text=True, check=True).stdout


def main():
    root = git('rev-parse', '--show-toplevel').strip()
    files = git('-C', root, 'diff', '--name-only').split()
    if not files:
        print('no file differs from the committed version: everything was reproduced byte-identical')
        return 0
    bad = 0
    for f in files:
        if not f.endswith('.json'):
            print('CHANGED (not JSON): %s' % f)
            bad += 1
            continue
        old = json.loads(git('-C', root, 'show', 'HEAD:' + f))
        with open(root + '/' + f) as fh:
            new = json.load(fh)
        st = {'n': 0, 'max_rel': 0.0, 'where': '', 'roundoff': 0.0, 'runtime': 0, 'detail': 0, 'errors': []}

        def walk(a, b, p):
            if isinstance(a, dict):
                if not isinstance(b, dict) or set(a) != set(b):
                    st['errors'].append('keys differ at %s' % p)
                    return
                for k in a:
                    walk(a[k], b[k], p + '/' + k)
            elif isinstance(a, list):
                if not isinstance(b, list) or len(a) != len(b):
                    st['errors'].append('array length differs at %s' % p)
                    return
                for i, (x, y) in enumerate(zip(a, b)):
                    walk(x, y, '%s[%d]' % (p, i))
            elif p.endswith('runtime_s'):
                st['runtime'] += a != b
            elif isinstance(a, bool) or a is None or isinstance(b, bool) or b is None:
                if a != b:
                    st['errors'].append('value differs at %s: %r -> %r' % (p, a, b))
            elif isinstance(a, (int, float)) and isinstance(b, (int, float)):
                st['n'] += 1
                if a != b:
                    scale = max(abs(a), abs(b))
                    if scale < 1e-10:
                        st['roundoff'] = max(st['roundoff'], abs(a - b))
                    elif abs(a - b) / scale > st['max_rel']:
                        st['max_rel'], st['where'] = abs(a - b) / scale, '%s: %r -> %r' % (p, a, b)
            elif a != b:
                if p.endswith('/detail'):
                    st['detail'] += 1
                else:
                    st['errors'].append('string differs at %s: %r -> %r' % (p, a, b))

        walk(old, new, '')
        verdict = 'OK' if not st['errors'] and st['max_rel'] <= TOL else 'DIFFERS'
        bad += verdict != 'OK'
        print('%-7s %s: %d numbers, largest relative difference %.2e %s; round-off-level absolute difference %.1e; '
              'run times differing %d; check details differing %d' % (
                  verdict, f, st['n'], st['max_rel'], ('(' + st['where'] + ')') if st['where'] else '', st['roundoff'],
                  st['runtime'], st['detail']))
        for e in st['errors'][:10]:
            print('        ' + e)
    print('result: %s (tolerance %.0e relative)' % ('REPRODUCED' if bad == 0 else 'NOT REPRODUCED', TOL))
    return 0 if bad == 0 else 1


if __name__ == '__main__':
    sys.exit(main())
